internal static class UiSymbols {
 public static void Draw(Control c,string kind,Vector2 p,float size,Color ink){Vector2 V(float x,float y)=>p+new Vector2(x,y)*size;void L(float x,float y,float a,float b,float t=2)=>c.DrawLine(V(x,y),V(a,b),ink,t,true);void R(float x,float y,float w,float h,bool fill=false)=>c.DrawRect(new Rect2(V(x,y),new Vector2(w,h)*size),ink,fill,fill?-1:1.5f,!fill);
  switch(kind){case "timber":R(.12f,.25f,.76f,.50f);L(.23f,.27f,.23f,.73f);L(.72f,.27f,.72f,.73f);L(.30f,.42f,.60f,.42f);break;case "stone":c.DrawPolyline(new[]{V(.12f,.78f),V(.08f,.43f),V(.35f,.14f),V(.72f,.20f),V(.93f,.56f),V(.72f,.85f),V(.12f,.78f)},ink,2,true);L(.35f,.14f,.46f,.52f);L(.46f,.52f,.93f,.56f);break;case "fiber":c.DrawArc(V(.48f,.51f),size*.32f,-2.6f,.8f,18,ink,2,true);c.DrawArc(V(.40f,.44f),size*.32f,.5f,3.4f,18,ink,2,true);L(.20f,.80f,.77f,.17f);break;case "resin":c.DrawPolyline(new[]{V(.50f,.05f),V(.20f,.55f),V(.18f,.75f),V(.35f,.92f),V(.65f,.92f),V(.82f,.75f),V(.80f,.55f),V(.50f,.05f)},ink,2,true);break;case "alloy":c.DrawPolyline(new[]{V(.08f,.70f),V(.25f,.28f),V(.78f,.28f),V(.94f,.70f),V(.80f,.86f),V(.20f,.86f),V(.08f,.70f)},ink,2,true);L(.08f,.70f,.94f,.70f);break;case "electronics":R(.25f,.25f,.50f,.50f);for(int j=0;j<3;j++){float v=.33f+j*.17f;L(.08f,v,.25f,v);L(.75f,v,.92f,v);L(v,.08f,v,.25f);L(v,.75f,v,.92f);}break;case "bio":c.DrawCircle(V(.50f,.30f),size*.12f,ink,false,2,true);c.DrawCircle(V(.20f,.72f),size*.12f,ink,false,2,true);c.DrawCircle(V(.80f,.72f),size*.12f,ink,false,2,true);L(.44f,.40f,.27f,.62f);L(.56f,.40f,.73f,.62f);L(.32f,.72f,.68f,.72f);break;case "weapon":R(.05f,.28f,.78f,.20f);L(.80f,.34f,1,.34f,3);L(.25f,.48f,.17f,.76f,4);L(.50f,.48f,.55f,.72f,3);break;case "armor":c.DrawPolyline(new[]{V(.12f,.12f),V(.32f,.08f),V(.40f,.24f),V(.60f,.24f),V(.68f,.08f),V(.88f,.12f),V(.82f,.91f),V(.18f,.91f),V(.12f,.12f)},ink,2,true);L(.28f,.48f,.72f,.48f);L(.28f,.68f,.72f,.68f);break;case "bandage":R(.14f,.14f,.72f,.72f);R(.39f,.27f,.22f,.46f,true);R(.27f,.39f,.46f,.22f,true);break;case "food":R(.23f,.17f,.54f,.68f);L(.23f,.28f,.77f,.28f);L(.23f,.72f,.77f,.72f);break;case "water":R(.35f,.04f,.30f,.15f);c.DrawPolyline(new[]{V(.35f,.19f),V(.22f,.35f),V(.22f,.90f),V(.78f,.90f),V(.78f,.35f),V(.65f,.19f)},ink,2,true);L(.24f,.63f,.76f,.63f);break;case "bag":R(.16f,.20f,.68f,.70f);c.DrawArc(V(.5f,.21f),size*.19f,Mathf.Pi,Mathf.Tau,16,ink,2,true);R(.28f,.59f,.44f,.20f);break;case "lamp":R(.12f,.38f,.45f,.23f);L(.57f,.38f,.82f,.21f);L(.57f,.61f,.82f,.78f);break;case "tools":L(.15f,.85f,.75f,.17f,3);R(.55f,.07f,.37f,.20f);L(.18f,.22f,.80f,.84f,3);break;case "catalyst":c.DrawPolyline(new[]{V(.5f,.04f),V(.91f,.5f),V(.5f,.96f),V(.09f,.5f),V(.5f,.04f)},ink,2,true);L(.5f,.20f,.5f,.80f);break;default:R(.14f,.22f,.72f,.60f);L(.14f,.42f,.86f,.42f);L(.36f,.22f,.36f,.82f);L(.65f,.22f,.65f,.82f);break;}
 }
}
